window.futvizVista("defensa","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"defensa\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"defensa\"]={\"id\":\"defensa\",\"titulo\":\"Goles recibidos vs. xG en contra\",\"bajada\":\"A la derecha, menos xG en contra; arriba, menos goles recibidos. Arriba a la derecha, los mejores.\",\"pregunta\":\"\u00bfQui\u00e9n defiende mejor y c\u00f3mo?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_con\",\"label\":\"xG en contra por partido (sin penales); menos, a la derecha\",\"corto\":\"xG en contra\",\"dec\":2,\"invertir\":true},\"y\":{\"col\":\"gol_con\",\"label\":\"Goles recibidos por partido (sin penales); menos, arriba\",\"corto\":\"Goles recibidos\",\"dec\":2,\"invertir\":true},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"goles recibidos \u2212 xG en contra\",\"sobre\":\"Reciben menos de lo esperado\",\"bajo\":\"Reciben m\u00e1s de lo esperado\",\"decDif\":2},\"requiere\":[\"xg_con\",\"gol_con\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG en contra\",\"ayuda\":\"Ordenados por xG en contra por partido (sin penales); menos, a la derecha: primero los que menos ocasiones conceden\"},{\"id\":\"y\",\"etiqueta\":\"Goles recibidos\",\"ayuda\":\"Ordenados por Goles recibidos por partido (sin penales); menos, arriba: primero los que menos goles reciben\"}],\"queMirar\":\"Compara los goles que recibe cada equipo con los que val\u00edan las ocasiones que concede, por partido y sin penales. El eje horizontal es el xG en contra y el vertical, los goles recibidos.\\nLos dos ejes van al rev\u00e9s, as\u00ed que cuanto m\u00e1s arriba y a la derecha, menos ocasiones concede y menos goles recibe. Sobre la diagonal el equipo recibe menos goles de los que val\u00edan esas ocasiones; debajo, m\u00e1s.\",\"insight\":\"defensa\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");